trait Data { public function jsonDB($lang, $dataFilesToLoad = null) { if ($dataFilesToLoad === null) { $dataFilesToLoad = array_keys($this->dataFiles); } $defaultConfig = self::JSONDB_DEFAULT_CONFIG; foreach ($dataFilesToLoad as $keys) { if (array_key_exists($keys, $this->dataFiles)) { $config = [ 'name' => $keys . '.json', 'dir' => $this->dataPath($keys, $lang), 'backup' => file_exists('site/data/.backup'), 'update' => false, ]; $dataFilesConfig = $this->getDataFilesConfig(); if (isset($dataFilesConfig[$keys])) { $config = array_merge($config, $defaultConfig, $dataFilesConfig[$keys]); } else { $config = array_merge($config, $defaultConfig); } $this->dataFiles[$keys] = new \Prowebcraft\JsonDb($config); } } } public function initData($module, $lang, $sampleSite = false) { require_once('core/module/install/resource/defaultdata.php'); if (!file_exists(self::DATA_DIR . $lang)) { mkdir(self::DATA_DIR . $lang, 0755); } switch ($module) { case 'page': case 'module': case 'locale': if (!file_exists(self::DATA_DIR . $lang)) { mkdir(self::DATA_DIR . $lang, 0755); } if (!file_exists(self::DATA_DIR . $lang . '/content')) { mkdir(self::DATA_DIR . $lang . '/content', 0755); } if ($lang == 'fr_FR' && $sampleSite === true && $module !== 'locale') { $this->setData([$module, \init::$siteTemplate[$module]]); foreach (\init::$siteContent as $key => $value) { $this->setPage($key, $value['content'], 'fr_FR'); } } else { $langDefault = array_key_exists($lang, \init::$defaultDataI18n) === true ? $lang : 'default'; $this->setData([$module, \init::$defaultDataI18n[$langDefault][$module]]); $pageId = \init::$defaultDataI18n[$langDefault]['locale']['homePageId']; $content = \init::$defaultDataI18n[$langDefault]['html']; $this->setPage($pageId, $content, $lang); } break; default: $this->setData([$module, \init::$defaultData[$module]]); break; } } private function loadDataFile($dataFile, $lang = null) { if ($lang === null) { $lang = self::$siteContent; } if (!array_key_exists($dataFile, $this->dataFiles) || empty($this->dataFiles[$dataFile])) { $config = [ 'name' => $dataFile . '.json', 'dir' => $this->dataPath($dataFile, $lang), 'backup' => file_exists('site/data/.backup'), 'update' => false, ]; if (isset($this->jsonDbConfig)) { $config = array_merge($config, $this->jsonDbConfig); } else { $config = array_merge($config, self::JSONDB_DEFAULT_CONFIG); } $dataFilesConfig = $this->getDataFilesConfig(); if (isset($dataFilesConfig[$dataFile])) { $config = array_merge($config, $dataFilesConfig[$dataFile]); } if (isset($config['encryption']) && $config['encryption'] && empty($config['encryptionKey'])) { $config['encryption'] = false; } $this->dataFiles[$dataFile] = new \Prowebcraft\JsonDb($config); } } protected function ensureDataFileLoaded($dataFile, $lang = null) { if ($lang === null) { $lang = self::$siteContent; } $this->loadDataFile($dataFile, $lang); } public function loadModuleDataFiles($moduleId, $lang = null) { if ($lang === null) { $lang = self::$siteContent; } $moduleRequiredBases = ['theme', 'font']; switch ($moduleId) { case 'user': case 'config': $moduleRequiredBases[] = 'admin'; $moduleRequiredBases[] = 'profil'; break; case 'blog': case 'news': $moduleRequiredBases[] = 'blacklist'; break; case 'language': $moduleRequiredBases[] = 'language'; break; } foreach ($moduleRequiredBases as $dataFile) { if (!$this->isDataFileLoaded($dataFile)) { $this->loadDataFile($dataFile, $lang); } } } public function setData($keys = [], $save = null) { $keys = $this->resolveModuleInstanceKeys($keys); if ( !empty(self::$inputNotices) or empty($keys) ) { return false; } if (!is_array($keys) || count($keys) < 2) { return false; } if (gettype($keys[count($keys) - 1]) === NULL) { return false; } if (empty($this->dataFiles[$keys[0]])) { $this->loadDataFile($keys[0]); } if (!isset($this->dataFiles[$keys[0]]) || empty($this->dataFiles[$keys[0]])) { return false; } $success = false; try { if (count($keys) >= 1) { $db = (object) $this->dataFiles[$keys[0]]; $query = $keys[0]; for ($i = 1; $i < count($keys) - 1; $i++) { $query .= '.' . $keys[$i]; } $success = $db->set($query, $keys[count($keys) - 1], $save); } } catch (Exception $e) { if (method_exists($this, 'saveLog')) { $this->saveLog('Erreur setData: ' . $e->getMessage() . ' pour les clés: ' . implode('.', $keys)); } return false; } return $success; } public function saveDataFile($dataFile, $data, $lang = null) { if ($lang === null) { $lang = self::$siteContent; } $this->loadDataFile($dataFile, $lang); $db = (object) $this->dataFiles[$dataFile]; $db->set($dataFile, $data); return $db->save(); } public function saveDB($module): void { if (empty($this->dataFiles[$module])) { throw new Exception("Tentative de sauvegarde d'une base non chargée : $module. La base doit être chargée avant d'être sauvegardée."); } $db = (object) $this->dataFiles[$module]; $db->save(); } public function getData($keys = []) { $keys = $this->resolveModuleInstanceKeys($keys); if (count($keys) >= 1) { if (empty($this->dataFiles[$keys[0]])) { $this->loadDataFile($keys[0]); } $db = (object) $this->dataFiles[$keys[0]]; $query = $keys[0]; for ($i = 1; $i < count($keys); $i++) { $query .= '.' . $keys[$i]; } return $db->get($query); } } public function fetchDataFile($dataFile, $lang = null, $query = null) { if ($lang === null) { $lang = self::$siteContent; } $config = [ 'name' => $dataFile . '.json', 'dir' => $this->dataPath($dataFile, $lang), 'backup' => file_exists('site/data/.backup'), ]; $config = isset($this->jsonDbConfig) ? array_merge($config, $this->jsonDbConfig) : array_merge($config, self::JSONDB_DEFAULT_CONFIG); $dataFilesConfig = $this->getDataFilesConfig(); if (isset($dataFilesConfig[$dataFile])) { $config = array_merge($config, $dataFilesConfig[$dataFile]); } if (isset($config['encryption']) && $config['encryption'] && empty($config['encryptionKey'])) { $config['encryption'] = false; } $db = new \Prowebcraft\JsonDb($config); if ($query === null) { $target = $dataFile; } elseif (is_array($query)) { $target = $dataFile; foreach ($query as $segment) { $target .= '.' . $segment; } } else { $target = $query; } return $db->get($target); } public function isDataFileLoaded($dataFile) { return array_key_exists($dataFile, $this->dataFiles) && !empty($this->dataFiles[$dataFile]); } private function getDataFilesConfig() { $configPath = self::DATA_DIR . 'config.json'; if (file_exists($configPath)) { $configData = json_decode(file_get_contents($configPath), true); if (isset($configData['config']['database'])) { return $configData['config']['database']; } } require_once('core/module/install/resource/defaultdata.php'); return \init::$dataFilesConfig ?? []; } public function deleteData($keys) { if (empty($this->dataFiles[$keys[0]])) { $this->loadDataFile($keys[0]); } $db = (object) $this->dataFiles[$keys[0]]; $query = $keys[0]; for ($i = 1; $i <= count($keys) - 1; $i++) { $query .= '.' . $keys[$i]; } $success = $db->delete($query, true); return is_object($success); } public function dataPath($id, $lang) { if ( $id === 'page' || $id === 'module' || $id === 'locale' ) { $folder = self::DATA_DIR . $lang . '/'; } else { $folder = self::DATA_DIR; } return ($folder); } protected static $moduleInstanceStack = []; protected static $moduleInstanceAnomalies = []; protected static function pushModuleInstance($instanceId, $pageId, $moduleId, $explicit = false) { self::$moduleInstanceStack[] = [ 'instanceId' => (string) $instanceId, 'pageId' => (string) $pageId, 'moduleId' => (string) $moduleId, 'explicit' => (bool) $explicit, ]; } protected static function popModuleInstance() { array_pop(self::$moduleInstanceStack); } protected static function getModuleInstance() { return self::$moduleInstanceStack === [] ? null : self::$moduleInstanceStack[count(self::$moduleInstanceStack) - 1]; } protected static function getModuleInstanceDepth() { return count(self::$moduleInstanceStack); } public static function getInstancePosition($instanceId) { $instanceId = (string) $instanceId; if (strpos($instanceId, '-free') !== false) { return 'free'; } if (substr($instanceId, -4) === '-top') { return 'top'; } if (substr($instanceId, -7) === '-bottom') { return 'bottom'; } return 'bottom'; } public static function isMultiInstanceAllowed($moduleId) { $moduleId = (string) $moduleId; if ($moduleId === '') { return false; } $multiModule = defined($moduleId . '::MULTIMODULE') ? $moduleId::MULTIMODULE : false; if ($multiModule !== true) { return false; } $singleInstance = defined($moduleId . '::SINGLEINSTANCE') ? $moduleId::SINGLEINSTANCE : false; return $singleInstance !== true; } public static function getModuleInstanceAnomalies() { return self::$moduleInstanceAnomalies; } protected function checkModuleInstanceContext($instanceId, $pageId, $moduleId) { $anomalies = []; $instanceId = (string) $instanceId; $pageId = (string) $pageId; $moduleId = (string) $moduleId; if ($this->getData(['page', $pageId]) === null) { if ($pageId !== $moduleId) { $anomalies[] = sprintf( 'page hôte introuvable [%s] pour l\'instance [%s] du module [%s]', $pageId, $instanceId, $moduleId ); } } else { $pageModules = $this->getData(['page', $pageId, 'pageModules']); if (!is_array($pageModules) || !array_key_exists($instanceId, $pageModules)) { $legacyModuleId = $this->getData(['page', $pageId, 'moduleId']); $legacyInstance = ($instanceId === $pageId); if (!($legacyInstance && $legacyModuleId === $moduleId)) { $anomalies[] = sprintf( 'instance [%s] non déclarée dans pageModules de la page [%s] (module instancié : %s)', $instanceId, $pageId, $moduleId ); } } else { $declaredModuleId = (string) ($pageModules[$instanceId]['moduleId'] ?? ''); if ($declaredModuleId !== '' && $declaredModuleId !== $moduleId) { $anomalies[] = sprintf( 'instance [%s] de la page [%s] déclarée pour le module [%s] mais instanciée avec [%s]', $instanceId, $pageId, $declaredModuleId, $moduleId ); } } } foreach ($anomalies as $anomaly) { if (!in_array($anomaly, self::$moduleInstanceAnomalies, true)) { self::$moduleInstanceAnomalies[] = $anomaly; if (method_exists($this, 'saveLog')) { $this->saveLog('Contexte d\'instance de module incohérent : ' . $anomaly); } } } return $anomalies; } protected static function resolveModuleInstanceUrl($url, $key = null) { if ($key === null) { return $url; } $parts = explode('/', $url); if (!array_key_exists($key, $parts)) { return null; } if ($key === 0) { $instance = self::getModuleInstance(); if ( $instance !== null && (string) $parts[0] === $instance['pageId'] && ( $instance['pageId'] !== $instance['instanceId'] || !empty($instance['explicit']) ) ) { $parts[0] = $instance['instanceId']; } } return $parts[$key]; } protected function resolveModuleInstanceKeys($keys) { if (!is_array($keys) || ($keys[0] ?? null) !== 'module') { return $keys; } $instance = self::getModuleInstance(); if ($instance === null) { return $keys; } $keyPage = (string) ($keys[1] ?? ''); if ($keyPage === (string) $instance['instanceId']) { return $keys; } if ($keyPage !== (string) $instance['pageId']) { return $keys; } $keys[1] = $instance['instanceId']; return $keys; } public function getPageId() { $instance = self::getModuleInstance(); if ($instance !== null && !empty($instance['pageId'])) { return $instance['pageId']; } return $this->getUrl(0); } public function getUrlArg($index) { if ($this->getPageId() === $this->getUrl(0)) { return $this->getUrl(2 + $index); } return $this->getUrl(3 + $index); } }
